// Arabic and French for SOP 1–11 checkpoints and the Health Code critical
// violation checkpoints (text and description). SOP 1–11 were transcribed
// from the client's own manual: the English stays the source of truth and
// these load as source='machine' until a native speaker reviews them.
// Temperatures stay in °F as written in the source.
import { byLanguage } from './rows.js';

export const sopItems = byLanguage([
  // --- Health Code Compliance — Critical Violation Checkpoints --------
  [`Food received only from approved, licensed suppliers`,
    `استلام الغذاء من موردين معتمدين ومرخّصين فقط`,
    `Aliments reçus uniquement de fournisseurs agréés et autorisés`],
  [`Accept deliveries only from approved, licensed vendors. Food from an unapproved source is a critical health code violation on its own, regardless of how the delivery itself looks or tastes.`,
    `اقبل التوريدات من موردين معتمدين ومرخّصين فقط. الغذاء القادم من مصدر غير معتمد يُعد مخالفة صحية حرجة بحد ذاته، بغض النظر عن مظهر الشحنة أو طعمها.`,
    `N'acceptez que les livraisons de fournisseurs agréés et autorisés. Un aliment de source non agréée constitue à lui seul une infraction sanitaire critique, quels que soient l'aspect ou le goût de la livraison.`],
  [`No bare hand contact with ready-to-eat food`,
    `عدم لمس الأطعمة الجاهزة للأكل باليد العارية`,
    `Aucun contact à mains nues avec les aliments prêts à consommer`],
  [`Ready-to-eat food (anything served without further cooking) must be handled with gloves, tongs, deli paper, or other utensils - never bare hands, even freshly washed ones. This is a distinct, commonly cited critical violation separate from general handwashing practice.`,
    `يجب التعامل مع الأطعمة الجاهزة للأكل (أي ما يُقدَّم دون طهي إضافي) بالقفازات أو الملاقط أو ورق التغليف أو أدوات أخرى - وليس باليد العارية أبدًا، حتى لو غُسلت للتو. وهذه مخالفة حرجة مستقلة وشائعة الرصد، منفصلة عن ممارسات غسل اليدين العامة.`,
    `Les aliments prêts à consommer (tout ce qui est servi sans cuisson supplémentaire) se manipulent avec des gants, des pinces, du papier alimentaire ou d'autres ustensiles - jamais à mains nues, même fraîchement lavées. C'est une infraction critique distincte et souvent relevée, indépendante du lavage des mains en général.`],
  [`Water supply and sewage systems functioning normally`,
    `إمدادات المياه وشبكة الصرف تعمل بشكل طبيعي`,
    `Alimentation en eau et évacuation des eaux usées fonctionnent normalement`],
  [`Confirm there is no loss of water supply and no sewage backup anywhere on the premises. Either condition is a critical violation with immediate-closure risk.`,
    `تأكد من عدم انقطاع المياه وعدم وجود أي ارتداد للصرف الصحي في أي مكان بالمنشأة. أي من الحالتين مخالفة حرجة قد تؤدي إلى الإغلاق الفوري.`,
    `Vérifiez qu'il n'y a ni coupure d'eau ni refoulement d'égout nulle part dans l'établissement. L'un ou l'autre est une infraction critique avec risque de fermeture immédiate.`],
  [`Certified food manager on-site during all operating hours`,
    `وجود مدير أغذية معتمد في الموقع طوال ساعات التشغيل`,
    `Responsable certifié en hygiène alimentaire présent pendant toutes les heures d'ouverture`],
  [`At least one staff member holding a current food manager certification (ServSafe or the local equivalent) must be present on-site during every hour of operation, not just scheduled to be.`,
    `يجب أن يكون موظف واحد على الأقل يحمل شهادة سارية لمدير الأغذية (ServSafe أو ما يعادلها محليًا) موجودًا فعليًا في الموقع خلال كل ساعة تشغيل، لا مجرد مُدرج في الجدول.`,
    `Au moins un membre de l'équipe titulaire d'une certification de responsable en hygiène alimentaire en cours de validité (ServSafe ou équivalent local) doit être réellement présent à chaque heure d'ouverture, pas seulement planifié.`],

  // --- SOP 1: Opening -------------------------------------------------
  [`Arrival and security check completed`,
    `إتمام الوصول والفحص الأمني`,
    `Arrivée et contrôle de sécurité effectués`],
  [`Unlock doors and disarm the alarm (note the time in the log). Walk the entire restaurant checking for signs of break-in or damage, water leaks or equipment issues, pest activity (droppings, damage), and unusual odors. If anything is found: document it, photograph it, and notify the manager immediately.`,
    `افتح الأبواب وأوقف الإنذار (سجّل الوقت في السجل). تجوّل في المطعم بالكامل للتحقق من علامات الاقتحام أو الأضرار، وتسربات المياه أو أعطال المعدات، ونشاط الآفات (فضلات، أضرار)، والروائح غير المعتادة. إذا وجدت شيئًا: وثّقه وصوّره وأبلغ المدير فورًا.`,
    `Déverrouillez les portes et désactivez l'alarme (notez l'heure dans le registre). Faites le tour complet du restaurant à la recherche de signes d'effraction ou de dégâts, de fuites d'eau ou de pannes d'équipement, d'activité de nuisibles (déjections, dégâts) et d'odeurs inhabituelles. En cas d'anomalie : documentez-la, photographiez-la et prévenez immédiatement le manager.`],
  [`Kitchen equipment startup completed`,
    `إتمام تشغيل معدات المطبخ`,
    `Mise en route des équipements de cuisine effectuée`],
  [`Turn on cooking equipment in sequence: ovens/ranges (30-45 min preheat), grills/griddles (20-30 min), fryers (fill to proper oil level, 15-20 min), steam tables and warmers, coffee makers and brewers. Confirm each reaches proper temperature, has no unusual sounds or smells, and that safety features (pilot lights, thermostats) work. Log any equipment issues in the maintenance log.`,
    `شغّل معدات الطهي بالترتيب: الأفران/المواقد (تسخين مسبق 30-45 دقيقة)، الشوايات/الصاجات (20-30 دقيقة)، القلايات (املأها لمستوى الزيت الصحيح، 15-20 دقيقة)، طاولات البخار وأجهزة التدفئة، ثم ماكينات القهوة والتحضير. تأكد أن كل جهاز يصل إلى الحرارة الصحيحة، وأنه بلا أصوات أو روائح غير معتادة، وأن وسائل الأمان (شعلات الإشعال، الثرموستات) تعمل. سجّل أي مشكلة في سجل الصيانة.`,
    `Allumez les équipements de cuisson dans l'ordre : fours/pianos (préchauffage 30-45 min), grills/planchas (20-30 min), friteuses (remplir au bon niveau d'huile, 15-20 min), bains-marie et chauffe-plats, machines à café et percolateurs. Vérifiez que chacun atteint la bonne température, sans bruit ni odeur inhabituels, et que les sécurités (veilleuses, thermostats) fonctionnent. Notez tout problème dans le registre de maintenance.`],
  [`Food safety checks completed`,
    `إتمام فحوصات سلامة الغذاء`,
    `Contrôles de sécurité alimentaire effectués`],
  [`Check and record refrigerator/freezer temperatures: walk-in cooler 37-40F, walk-in freezer 0F or below, reach-in coolers 37-40F. If anything is out of range, notify the manager and do not use it until corrected. Check food dating and rotation: remove expired items, verify FIFO, and check for signs of spoilage.`,
    `افحص وسجّل درجات حرارة الثلاجات والفريزرات: غرفة التبريد 37-40 °ف، غرفة التجميد 0 °ف أو أقل، الثلاجات القائمة 37-40 °ف. إذا كان أي منها خارج النطاق، أبلغ المدير ولا تستخدمه حتى يُصلح. افحص تواريخ الأطعمة وتدويرها: أزل المنتهي الصلاحية، وتحقق من تطبيق الوارد أولًا صادر أولًا، وابحث عن علامات الفساد.`,
    `Contrôlez et notez les températures des froids : chambre froide positive 37-40 °F, chambre froide négative 0 °F ou moins, armoires réfrigérées 37-40 °F. Si une valeur est hors plage, prévenez le manager et n'utilisez pas l'équipement avant correction. Vérifiez les dates et la rotation : retirez les produits périmés, contrôlez le PEPS et recherchez tout signe d'altération.`],
  [`Station prep and mise en place completed`,
    `إتمام تجهيز المحطات والميز أون بلاس`,
    `Préparation des postes et mise en place effectuées`],
  [`Set up each cooking station: stock ingredients, prepare mise en place per prep lists, arrange tools within reach. Slice, dice, and portion as needed; prepare sauces and dressings; pre-cook items requiring advance prep. Label and date everything prepared.`,
    `جهّز كل محطة طهي: زوّدها بالمكونات، وحضّر الميز أون بلاس وفق قوائم التحضير، ورتّب الأدوات في متناول اليد. قطّع وقسّم الحصص حسب الحاجة؛ حضّر الصلصات والتتبيلات؛ اطهُ مسبقًا ما يحتاج تحضيرًا مبكرًا. ضع ملصقًا وتاريخًا على كل ما تم تحضيره.`,
    `Installez chaque poste de cuisson : approvisionnez les ingrédients, préparez la mise en place selon les listes de préparation, disposez les outils à portée de main. Taillez et portionnez au besoin ; préparez sauces et assaisonnements ; précuisez ce qui doit l'être. Étiquetez et datez tout ce qui est préparé.`],
  [`Dining room setup completed`,
    `إتمام تجهيز صالة الطعام`,
    `Mise en place de la salle effectuée`],
  [`Unlock and clean entrance doors, turn on dining room lights, set a comfortable thermostat. Check and stock restrooms (toilet paper, towels, soap; clean mirrors/fixtures; empty trash; confirm accessibility). Clean and set tables, fold napkins, check table stability. Stock server stations (silverware, napkins, condiments, beverages) and confirm the POS system is operational and menus are clean and complete.`,
    `افتح أبواب المدخل ونظّفها، وشغّل إضاءة الصالة، واضبط التكييف على درجة مريحة. افحص دورات المياه وزوّدها (ورق التواليت، المناشف، الصابون؛ نظّف المرايا والتجهيزات؛ أفرغ القمامة؛ تأكد من سهولة الوصول). نظّف الطاولات وجهّزها، واطوِ المناديل، وتأكد من ثبات الطاولات. زوّد محطات الخدمة (أدوات المائدة، المناديل، التوابل، المشروبات) وتأكد أن نظام نقاط البيع يعمل وأن القوائم نظيفة ومكتملة.`,
    `Déverrouillez et nettoyez les portes d'entrée, allumez la salle, réglez le thermostat sur une température agréable. Contrôlez et approvisionnez les toilettes (papier, essuie-mains, savon ; miroirs et équipements nettoyés ; poubelles vidées ; accessibilité vérifiée). Nettoyez et dressez les tables, pliez les serviettes, vérifiez leur stabilité. Approvisionnez les postes de service (couverts, serviettes, condiments, boissons) et vérifiez que la caisse fonctionne et que les cartes sont propres et complètes.`],
  [`Pre-service meeting held`,
    `عقد اجتماع ما قبل الخدمة`,
    `Briefing avant service tenu`],
  [`Brief the team on daily specials, 86'd items, reservations and expected volume, special requests or VIP guests, and any equipment issues or limitations. Assign sections and responsibilities, answer questions, and set expectations for the shift.`,
    `أطلع الفريق على الأطباق الخاصة اليومية، والأصناف النافدة، والحجوزات وحجم العمل المتوقع، والطلبات الخاصة أو كبار الضيوف، وأي أعطال أو قيود في المعدات. وزّع الأقسام والمسؤوليات، وأجب عن الأسئلة، وحدّد التوقعات للوردية.`,
    `Informez l'équipe des suggestions du jour, des plats épuisés, des réservations et de l'affluence attendue, des demandes particulières ou clients VIP, et de tout problème ou limite d'équipement. Attribuez les rangs et responsabilités, répondez aux questions et fixez les attentes du service.`],
  [`Final opening checklist verified`,
    `التحقق من قائمة الافتتاح النهائية`,
    `Check-list finale d'ouverture vérifiée`],
  [`Confirm: kitchen ready (all stations stocked and operational); dining room ready (clean, set, welcoming); staff ready (uniformed, informed, sections assigned); systems ready (POS, phones, music); safety ready (first aid kit accessible, exits clear).`,
    `تأكد من: جاهزية المطبخ (جميع المحطات مجهزة وتعمل)؛ جاهزية الصالة (نظيفة، مجهزة، مرحّبة)؛ جاهزية الفريق (بالزي الرسمي، على اطلاع، الأقسام موزعة)؛ جاهزية الأنظمة (نقاط البيع، الهواتف، الموسيقى)؛ جاهزية السلامة (حقيبة الإسعافات متاحة، المخارج خالية).`,
    `Confirmez : cuisine prête (tous les postes approvisionnés et opérationnels) ; salle prête (propre, dressée, accueillante) ; équipe prête (en tenue, informée, rangs attribués) ; systèmes prêts (caisse, téléphones, musique) ; sécurité prête (trousse de secours accessible, issues dégagées).`],
  [`Open for service`,
    `الفتح للخدمة`,
    `Ouverture au service`],
  [`Unlock the front doors, turn on the "Open" sign, and have the host greet the first guests.`,
    `افتح الأبواب الأمامية، وشغّل لافتة «مفتوح»، ودع موظف الاستقبال يرحّب بأول الضيوف.`,
    `Déverrouillez les portes d'entrée, allumez l'enseigne « Ouvert » et laissez l'hôte accueillir les premiers clients.`],

  // --- SOP 2: Closing -------------------------------------------------
  [`Kitchen breakdown and cleaning completed`,
    `إتمام تفكيك المطبخ وتنظيفه`,
    `Démontage et nettoyage de la cuisine effectués`],
  [`Stop accepting new orders and complete pending ones. Break down stations: clean and cover food, store by temperature, label with date/time, rotate for FIFO. Clean cooking equipment (grills scraped and degreased, fryer oil filtered or changed, ovens wiped, range burners and drip pans cleaned). Wash and sanitize work surfaces and air dry. Sweep and mop kitchen floors including corners and drains, and clean the mop bucket.`,
    `توقف عن قبول طلبات جديدة وأكمل الطلبات المعلقة. فكّك المحطات: نظّف الطعام وغطّه، وخزّنه حسب درجة الحرارة، وضع عليه التاريخ والوقت، ودوّره وفق الوارد أولًا صادر أولًا. نظّف معدات الطهي (كشط الشوايات وإزالة الدهون، تصفية زيت القلاية أو تغييره، مسح الأفران، تنظيف شعلات المواقد وصواني التقطير). اغسل أسطح العمل وعقّمها واتركها تجف في الهواء. اكنس أرضيات المطبخ وامسحها بما فيها الزوايا والمصارف، ونظّف دلو المسح.`,
    `Cessez de prendre de nouvelles commandes et terminez celles en cours. Démontez les postes : nettoyez et couvrez les aliments, stockez-les selon leur température, étiquetez date/heure, appliquez le PEPS. Nettoyez les équipements de cuisson (grills grattés et dégraissés, huile de friture filtrée ou changée, fours essuyés, brûleurs et lèchefrites nettoyés). Lavez et désinfectez les plans de travail, séchage à l'air. Balayez et lavez les sols de la cuisine, coins et siphons compris, et nettoyez le seau.`],
  [`Dining room closing completed`,
    `إتمام إغلاق صالة الطعام`,
    `Fermeture de la salle effectuée`],
  [`Lock the front doors and turn off the "Open" sign. Clear and clean all tables, reset for next day if needed. Vacuum or sweep the dining room, spot-mop spills, clean and restock restrooms, and take out all trash and recycling with fresh liners.`,
    `أغلق الأبواب الأمامية وأطفئ لافتة «مفتوح». ارفع جميع الطاولات ونظّفها، وأعد تجهيزها لليوم التالي إن لزم. نظّف الصالة بالمكنسة الكهربائية أو اكنسها، وامسح الانسكابات، ونظّف دورات المياه وأعد تزويدها، وأخرج كل القمامة والمواد القابلة للتدوير مع وضع أكياس جديدة.`,
    `Verrouillez les portes d'entrée et éteignez l'enseigne « Ouvert ». Débarrassez et nettoyez toutes les tables, redressez-les pour le lendemain si besoin. Aspirez ou balayez la salle, épongez les taches, nettoyez et réapprovisionnez les toilettes, et sortez tous les déchets et le recyclage en remettant des sacs neufs.`],
  [`Equipment shutdown completed`,
    `إتمام إيقاف تشغيل المعدات`,
    `Arrêt des équipements effectué`],
  [`Turn off cooking equipment in reverse order, ensure fryers are covered, and turn off coffee makers after emptying and cleaning them. Run the dishwasher through a final cycle, then clean and drain it. Turn off ice machines if scheduled, and adjust HVAC to overnight settings.`,
    `أطفئ معدات الطهي بترتيب عكسي، وتأكد من تغطية القلايات، وأطفئ ماكينات القهوة بعد تفريغها وتنظيفها. شغّل غسالة الأطباق دورة أخيرة ثم نظّفها وصرّفها. أطفئ ماكينات الثلج إن كان ذلك مجدولًا، واضبط التكييف على إعدادات الليل.`,
    `Éteignez les équipements de cuisson dans l'ordre inverse, couvrez les friteuses et éteignez les machines à café après les avoir vidées et nettoyées. Faites un dernier cycle de lave-vaisselle, puis nettoyez-le et vidangez-le. Éteignez les machines à glaçons si prévu et passez la climatisation en mode nuit.`],
  [`Cash handling and POS closing completed`,
    `إتمام التعامل النقدي وإغلاق نقاط البيع`,
    `Gestion des espèces et clôture de caisse effectuées`],
  [`Count each cash drawer by denomination, total and verify against the POS, and investigate any discrepancy. Prepare the bank deposit: leave starting cash in the drawer, deposit the remainder per policy, complete the deposit slip, and secure it. Close the POS: run end-of-day reports, print the sales summary, verify the credit card batch, and back up data.`,
    `عدّ كل درج نقدي حسب الفئات، واجمعه وطابقه مع نقاط البيع، وتحقق من أي فرق. جهّز الإيداع البنكي: اترك النقدية الافتتاحية في الدرج، وأودع الباقي وفق السياسة، واملأ إيصال الإيداع وأمّنه. أغلق نقاط البيع: استخرج تقارير نهاية اليوم، واطبع ملخص المبيعات، وتحقق من دفعة البطاقات الائتمانية، واحفظ نسخة احتياطية من البيانات.`,
    `Comptez chaque tiroir-caisse par coupure, totalisez et rapprochez avec la caisse, et analysez tout écart. Préparez le dépôt bancaire : laissez le fond de caisse dans le tiroir, déposez le reste selon la procédure, remplissez le bordereau et mettez-le en sécurité. Clôturez la caisse : éditez les rapports de fin de journée, imprimez le récapitulatif des ventes, vérifiez le lot de cartes bancaires et sauvegardez les données.`],
  [`Food storage final check completed`,
    `إتمام الفحص النهائي لتخزين الطعام`,
    `Contrôle final du stockage effectué`],
  [`Walk through all coolers and storage. Verify all food is properly covered and stored, labeled and dated, and that proper temperature zones are maintained. Lock walk-ins if applicable.`,
    `تجوّل في جميع الثلاجات والمخازن. تحقق أن كل الطعام مغطى ومخزن بشكل صحيح، وعليه ملصق وتاريخ، وأن نطاقات الحرارة الصحيحة محفوظة. أقفل غرف التبريد إن وُجدت.`,
    `Faites le tour de tous les froids et réserves. Vérifiez que tous les aliments sont couverts, bien stockés, étiquetés et datés, et que les bonnes zones de température sont respectées. Verrouillez les chambres froides le cas échéant.`],
  [`Next-day prep completed`,
    `إتمام التحضير لليوم التالي`,
    `Préparation du lendemain effectuée`],
  [`Check tomorrow's prep list. Pull frozen items to thaw overnight if safe to do so, prep any time-intensive items, note inventory needs on the order sheet, and set timers for morning equipment startup.`,
    `راجع قائمة تحضير الغد. انقل المجمدات لتذوب خلال الليل إن كان ذلك آمنًا، وحضّر الأصناف التي تستغرق وقتًا طويلًا، ودوّن احتياجات المخزون في ورقة الطلب، واضبط مؤقتات تشغيل المعدات صباحًا.`,
    `Consultez la liste de préparation du lendemain. Sortez les surgelés à décongeler pendant la nuit si c'est sans risque, préparez les éléments longs à réaliser, notez les besoins de stock sur le bon de commande et programmez les minuteurs de mise en route du matin.`],
  [`Security and final walkthrough completed`,
    `إتمام الأمن والجولة النهائية`,
    `Sécurité et tour final effectués`],
  [`Turn off unnecessary lights (leave security lights on) and check all doors and windows are locked. Verify oven/range burners are off and no water is running. Confirm the back door is secure, set the alarm system, exit through the designated door, and lock and verify the final door. Note the closing time in the log.`,
    `أطفئ الأضواء غير الضرورية (اترك أضواء الأمن مضاءة) وتأكد أن جميع الأبواب والنوافذ مقفلة. تحقق أن الأفران وشعلات المواقد مطفأة ولا مياه جارية. تأكد من تأمين الباب الخلفي، وفعّل نظام الإنذار، واخرج من الباب المخصص، ثم أقفل الباب الأخير وتحقق منه. سجّل وقت الإغلاق في السجل.`,
    `Éteignez les lumières inutiles (laissez l'éclairage de sécurité) et vérifiez que portes et fenêtres sont verrouillées. Contrôlez que fours et brûleurs sont éteints et qu'aucune eau ne coule. Vérifiez que la porte arrière est sécurisée, activez l'alarme, sortez par la porte prévue, puis verrouillez et contrôlez la dernière porte. Notez l'heure de fermeture dans le registre.`],

  // --- SOP 3: Receiving & Storage -------------------------------------
  [`Delivery acceptance verified`,
    `التحقق من قبول التوريد`,
    `Acceptation de la livraison vérifiée`],
  [`Confirm the delivery is scheduled and from an approved vendor. Check the driver's cleanliness and food-handling practices, and check the delivery vehicle for clean condition, proper refrigeration (if a cold truck), and no cross-contamination with non-food items.`,
    `تأكد أن التوريد مجدول ومن مورد معتمد. افحص نظافة السائق وممارساته في التعامل مع الغذاء، وافحص مركبة التوصيل للتأكد من نظافتها، وسلامة التبريد (إن كانت مبردة)، وعدم وجود تلوث متبادل مع مواد غير غذائية.`,
    `Vérifiez que la livraison est prévue et provient d'un fournisseur agréé. Contrôlez la propreté du chauffeur et ses pratiques d'hygiène, ainsi que le véhicule : propre, correctement réfrigéré (camion frigorifique) et sans contamination croisée avec des produits non alimentaires.`],
  [`Product inspection completed`,
    `إتمام فحص المنتجات`,
    `Contrôle des produits effectué`],
  [`Check the invoice against delivery contents and verify quantities and product codes. Inspect temperature (cold foods 41F or below, frozen foods 0F or below solid frozen, hot foods 135F or above - reject if not met), packaging (intact, no dented/bulging/rusted cans, vacuum seals intact), and quality (produce free of mold or soft spots, meat/poultry proper color and odor within sell-by date, seafood ocean-fresh smell with clear eyes and firm flesh, dairy within expiration with proper consistency). If anything fails: reject immediately, note the rejection on the invoice, photograph evidence, and contact the vendor about credit or replacement.`,
    `طابق الفاتورة مع محتويات التوريد وتحقق من الكميات وأكواد المنتجات. افحص الحرارة (الأطعمة الباردة 41 °ف أو أقل، المجمدة 0 °ف أو أقل ومتجمدة تمامًا، الساخنة 135 °ف أو أعلى - ارفضها إن لم تستوفِ ذلك)، والتغليف (سليم، لا علب منبعجة أو منتفخة أو صدئة، أختام التفريغ سليمة)، والجودة (الخضار والفواكه خالية من العفن أو البقع الطرية، اللحوم والدواجن بلون ورائحة سليمين وضمن تاريخ البيع، المأكولات البحرية برائحة البحر الطازجة وعيون صافية ولحم متماسك، الألبان ضمن الصلاحية وبقوام سليم). إذا فشل أي شيء: ارفضه فورًا، ودوّن الرفض على الفاتورة، وصوّر الدليل، وتواصل مع المورد بشأن الخصم أو الاستبدال.`,
    `Rapprochez la facture du contenu livré et vérifiez quantités et codes produits. Contrôlez la température (produits froids 41 °F ou moins, surgelés 0 °F ou moins et bien congelés, produits chauds 135 °F ou plus - refuser sinon), l'emballage (intact, pas de boîtes cabossées, bombées ou rouillées, sous-vide intact) et la qualité (fruits et légumes sans moisissure ni zones molles, viandes et volailles de couleur et d'odeur normales dans leur date limite, produits de la mer à l'odeur marine fraîche, yeux clairs et chair ferme, produits laitiers dans leur date et de bonne consistance). En cas de non-conformité : refusez immédiatement, notez le refus sur la facture, photographiez la preuve et contactez le fournisseur pour avoir ou remplacement.`],
  [`Immediate storage completed within 15 minutes`,
    `إتمام التخزين الفوري خلال 15 دقيقة`,
    `Stockage immédiat effectué en moins de 15 minutes`],
  [`Store refrigerated and frozen items within 15 minutes of delivery - perishables first, then shelf-stable items. Do not leave items at room temperature.`,
    `خزّن الأصناف المبردة والمجمدة خلال 15 دقيقة من التوريد - القابلة للتلف أولًا، ثم الأصناف الجافة. لا تترك أي أصناف في حرارة الغرفة.`,
    `Rangez les produits réfrigérés et surgelés dans les 15 minutes suivant la livraison - les périssables d'abord, puis les produits stables. Ne laissez rien à température ambiante.`],
  [`Storage by type organized correctly`,
    `تنظيم التخزين حسب النوع بشكل صحيح`,
    `Stockage par type correctement organisé`],
  [`Refrigerated (37-40F): ready-to-eat/cooked foods on top, seafood and whole cuts of meat in the middle, raw ground meat and poultry on the bottom to prevent dripping; keep raw separate from ready-to-eat, in original packaging or covered containers. Frozen (0F or below): organized by product type, labeled with receive date, rotated FIFO, not overloaded so air can circulate. Dry storage (50-70F): shelves 6 inches off the floor and away from walls, rotated FIFO, chemicals stored separate from food, dry goods in sealed containers.`,
    `المبرد (37-40 °ف): الأطعمة الجاهزة/المطهوة في الأعلى، والمأكولات البحرية وقطع اللحم الكاملة في المنتصف، واللحم المفروم النيء والدواجن في الأسفل لمنع التقطير؛ افصل النيء عن الجاهز للأكل، في عبوته الأصلية أو في حاويات مغطاة. المجمد (0 °ف أو أقل): مرتب حسب نوع المنتج، وعليه تاريخ الاستلام، ومدوَّر وفق الوارد أولًا صادر أولًا، وغير مكدس حتى يدور الهواء. التخزين الجاف (50-70 °ف): الأرفف مرتفعة 6 بوصات عن الأرض وبعيدة عن الجدران، مدوَّرة وفق الوارد أولًا صادر أولًا، والمواد الكيميائية منفصلة عن الطعام، والمواد الجافة في حاويات محكمة الإغلاق.`,
    `Réfrigéré (37-40 °F) : prêts à consommer/cuits en haut, produits de la mer et pièces de viande entières au milieu, viande hachée crue et volaille en bas pour éviter les écoulements ; séparez le cru du prêt à consommer, dans l'emballage d'origine ou en bacs couverts. Surgelé (0 °F ou moins) : rangé par type de produit, étiqueté avec la date de réception, en PEPS, sans surcharge pour laisser circuler l'air. Stockage sec (50-70 °F) : étagères à 6 pouces du sol et loin des murs, en PEPS, produits chimiques séparés des aliments, denrées sèches en contenants fermés.`],
  [`Labeling and dating completed`,
    `إتمام الوسم والتأريخ`,
    `Étiquetage et datage effectués`],
  [`Label every item with product name, receive date or use-by date, and open date if the container has been opened. Use waterproof labels or markers placed where clearly visible.`,
    `ضع على كل صنف ملصقًا باسم المنتج، وتاريخ الاستلام أو تاريخ انتهاء الاستخدام، وتاريخ الفتح إن فُتحت العبوة. استخدم ملصقات أو أقلامًا مقاومة للماء في مكان واضح.`,
    `Étiquetez chaque produit avec son nom, la date de réception ou la DLC, et la date d'ouverture si le contenant est entamé. Utilisez des étiquettes ou marqueurs résistants à l'eau, placés bien en vue.`],
  [`FIFO rotation verified`,
    `التحقق من تدوير الوارد أولًا صادر أولًا`,
    `Rotation PEPS vérifiée`],
  [`Place new stock behind existing stock and use older items first. Check dates weekly and remove expired items immediately.`,
    `ضع المخزون الجديد خلف المخزون الموجود واستخدم الأقدم أولًا. افحص التواريخ أسبوعيًا وأزل المنتهي الصلاحية فورًا.`,
    `Placez le nouveau stock derrière l'existant et utilisez d'abord les produits les plus anciens. Vérifiez les dates chaque semaine et retirez immédiatement les produits périmés.`],
  [`Receiving log completed`,
    `إتمام سجل الاستلام`,
    `Registre de réception complété`],
  [`Record date and time, vendor name, products received, temperatures checked, any rejections, and the staff member who received the delivery.`,
    `سجّل التاريخ والوقت، واسم المورد، والمنتجات المستلمة، ودرجات الحرارة المقاسة، وأي مرفوضات، والموظف الذي استلم التوريد.`,
    `Notez la date et l'heure, le fournisseur, les produits reçus, les températures relevées, les éventuels refus et la personne qui a réceptionné la livraison.`],

  // --- SOP 4: Temperature Monitoring ----------------------------------
  [`Thermometer calibration completed`,
    `إتمام معايرة موازين الحرارة`,
    `Étalonnage des thermomètres effectué`],
  [`Calibrate all food thermometers weekly using the ice water method: fill a cup with ice and water, insert the thermometer stem, and confirm it reads 32F (adjust if not). Replace any thermometer that won't calibrate.`,
    `عاير جميع موازين حرارة الطعام أسبوعيًا بطريقة الماء المثلج: املأ كوبًا بالثلج والماء، وأدخل ساق الميزان، وتأكد أنه يقرأ 32 °ف (اضبطه إن لم يكن كذلك). استبدل أي ميزان لا يمكن معايرته.`,
    `Étalonnez chaque semaine tous les thermomètres alimentaires par la méthode de l'eau glacée : remplissez un verre de glace et d'eau, plongez la tige et vérifiez qu'il affiche 32 °F (ajustez sinon). Remplacez tout thermomètre impossible à étalonner.`],
  [`Cooking temperatures verified`,
    `التحقق من درجات حرارة الطهي`,
    `Températures de cuisson vérifiées`],
  [`Check internal (not surface) temperature in the thickest part of the item, avoiding bone, fat, or pan, and wait for the reading to stabilize. Minimum temperatures: 165F for poultry, stuffed meats, casseroles, and reheated leftovers; 155F for ground/injected meats and eggs for hot holding; 145F for whole cuts of beef/pork/lamb/veal, fish, and eggs for immediate service; 135F for vegetables, fruits, grains, and legumes held hot. If not met, keep cooking and recheck. Clean and sanitize the thermometer between uses, and log the temperature.`,
    `قِس الحرارة الداخلية (لا السطحية) في أسمك جزء من الصنف، متجنبًا العظم أو الدهن أو الوعاء، وانتظر حتى تستقر القراءة. الحد الأدنى: 165 °ف للدواجن واللحوم المحشوة والطواجن وبقايا الطعام المعاد تسخينها؛ 155 °ف للحوم المفرومة/المحقونة والبيض المحفوظ ساخنًا؛ 145 °ف لقطع اللحم البقري/الخنزير/الضأن/العجل الكاملة والأسماك والبيض للتقديم الفوري؛ 135 °ف للخضار والفواكه والحبوب والبقوليات المحفوظة ساخنة. إن لم تتحقق، واصل الطهي وأعد القياس. نظّف الميزان وعقّمه بين الاستخدامات، وسجّل الحرارة.`,
    `Mesurez la température interne (pas en surface) dans la partie la plus épaisse, en évitant os, gras ou récipient, et attendez que la lecture se stabilise. Minimums : 165 °F pour volailles, viandes farcies, gratins et restes réchauffés ; 155 °F pour viandes hachées/injectées et œufs maintenus au chaud ; 145 °F pour pièces entières de bœuf/porc/agneau/veau, poissons et œufs servis immédiatement ; 135 °F pour légumes, fruits, céréales et légumineuses maintenus au chaud. Sinon, poursuivez la cuisson et remesurez. Nettoyez et désinfectez le thermomètre entre chaque usage et notez la température.`],
  [`Two-stage cooling procedure followed`,
    `اتباع إجراء التبريد على مرحلتين`,
    `Procédure de refroidissement en deux étapes respectée`],
  [`Cool from 135F to 70F within 2 hours, then from 70F to 41F within another 4 hours - 6 hours total, maximum. Use shallow containers (2-3 inches deep), divide large batches, use an ice bath, stir frequently, and leave uncovered or loosely covered until cooled. Never put hot food directly in the cooler. Check temperature every 30-60 minutes and log times/temps. If cooling too slowly, adjust technique immediately; if the 6-hour window is exceeded, discard the food.`,
    `برّد من 135 °ف إلى 70 °ف خلال ساعتين، ثم من 70 °ف إلى 41 °ف خلال 4 ساعات أخرى - 6 ساعات كحد أقصى إجمالًا. استخدم حاويات ضحلة (بعمق 2-3 بوصات)، وقسّم الدفعات الكبيرة، واستخدم حمام الثلج، وقلّب كثيرًا، واتركها مكشوفة أو مغطاة تغطية خفيفة حتى تبرد. لا تضع الطعام الساخن مباشرة في الثلاجة أبدًا. قِس الحرارة كل 30-60 دقيقة وسجّل الأوقات والدرجات. إن كان التبريد بطيئًا، عدّل الطريقة فورًا؛ وإن تجاوزت مدة الـ 6 ساعات، تخلّص من الطعام.`,
    `Refroidissez de 135 °F à 70 °F en 2 heures, puis de 70 °F à 41 °F en 4 heures supplémentaires - 6 heures au total, maximum. Utilisez des bacs peu profonds (2-3 pouces), divisez les grandes quantités, utilisez un bain de glace, remuez souvent et laissez découvert ou légèrement couvert jusqu'à refroidissement. Ne mettez jamais un aliment chaud directement au froid. Contrôlez la température toutes les 30-60 minutes et notez heures et températures. Si le refroidissement est trop lent, corrigez immédiatement ; si les 6 heures sont dépassées, jetez l'aliment.`],
  [`Reheating for hot holding completed`,
    `إتمام إعادة التسخين للحفظ الساخن`,
    `Remise en température pour maintien au chaud effectuée`],
  [`Reheat leftovers to 165F within 2 hours, checking multiple spots including thick portions and the center, and stirring for even heat. Reheat only once - never cool and reheat the same batch more than once. After reheating, hold at 135F or above.`,
    `أعد تسخين البقايا إلى 165 °ف خلال ساعتين، مع القياس في عدة نقاط منها الأجزاء السميكة والمنتصف، والتقليب لتوزيع الحرارة. أعد التسخين مرة واحدة فقط - لا تبرّد الدفعة نفسها وتعيد تسخينها أكثر من مرة. بعد إعادة التسخين، احفظها عند 135 °ف أو أعلى.`,
    `Réchauffez les restes à 165 °F en 2 heures, en mesurant à plusieurs endroits dont les parties épaisses et le centre, et en remuant pour une chaleur homogène. Une seule remise en température - ne refroidissez et ne réchauffez jamais un même lot plus d'une fois. Ensuite, maintenez à 135 °F ou plus.`],
  [`Hot holding temperatures verified`,
    `التحقق من درجات حرارة الحفظ الساخن`,
    `Températures de maintien au chaud vérifiées`],
  [`Check steam tables and warmers every 2 hours and log the reading; food must stay at 135F or above. If below 135F: reheat to 165F if it is still above 70F and has been under 2 hours, otherwise discard. Stir periodically and keep pans covered.`,
    `افحص طاولات البخار وأجهزة التدفئة كل ساعتين وسجّل القراءة؛ يجب أن يبقى الطعام عند 135 °ف أو أعلى. إن كان أقل من 135 °ف: أعد تسخينه إلى 165 °ف إن كان لا يزال فوق 70 °ف ومضى أقل من ساعتين، وإلا فتخلّص منه. قلّب دوريًا وأبقِ الأوعية مغطاة.`,
    `Contrôlez bains-marie et chauffe-plats toutes les 2 heures et notez la valeur ; les aliments doivent rester à 135 °F ou plus. En dessous de 135 °F : réchauffez à 165 °F s'ils sont encore au-dessus de 70 °F depuis moins de 2 heures, sinon jetez-les. Remuez régulièrement et gardez les bacs couverts.`],
  [`Cold holding temperatures verified`,
    `التحقق من درجات حرارة الحفظ البارد`,
    `Températures de maintien au froid vérifiées`],
  [`Check salad bars and prep coolers every 2 hours; food must stay at 41F or below. If above 41F: re-chill rapidly if it is still under 70F and has been under 4 hours, otherwise discard.`,
    `افحص بارات السلطة وثلاجات التحضير كل ساعتين؛ يجب أن يبقى الطعام عند 41 °ف أو أقل. إن كان فوق 41 °ف: أعد تبريده بسرعة إن كان لا يزال تحت 70 °ف ومضى أقل من 4 ساعات، وإلا فتخلّص منه.`,
    `Contrôlez bars à salade et saladettes toutes les 2 heures ; les aliments doivent rester à 41 °F ou moins. Au-dessus de 41 °F : refroidissez rapidement s'ils sont encore sous 70 °F depuis moins de 4 heures, sinon jetez-les.`],
  [`Time as Public Health Control (TPHC) applied correctly`,
    `تطبيق التحكم بالوقت كإجراء للصحة العامة (TPHC) بشكل صحيح`,
    `Contrôle par le temps (TPHC) correctement appliqué`],
  [`If using time instead of temperature control, mark the food with a discard time 4 hours from when it was removed from temperature control, and discard it after 4 hours even if it looks or smells fine. Once at room temperature under this method, it cannot go back into the cooler.`,
    `إذا استخدمت الوقت بدلًا من التحكم بالحرارة، فضع على الطعام وقت التخلص منه بعد 4 ساعات من إخراجه من التحكم بالحرارة، وتخلّص منه بعد 4 ساعات حتى لو بدا شكله أو رائحته سليمين. بعد وصوله لحرارة الغرفة بهذه الطريقة، لا يجوز إعادته إلى الثلاجة.`,
    `Si vous utilisez le temps au lieu de la température, indiquez sur l'aliment une heure de mise au rebut 4 heures après sa sortie du contrôle de température, et jetez-le au bout de 4 heures même s'il paraît et sent bon. Une fois à température ambiante selon cette méthode, il ne peut pas retourner au froid.`],

  // --- SOP 5: Handwashing & Hygiene -----------------------------------
  [`Handwashing performed correctly and at required times`,
    `غسل اليدين بشكل صحيح وفي الأوقات المطلوبة`,
    `Lavage des mains correct et aux moments requis`],
  [`Wash hands before starting work; after the restroom; after touching hair, face, or body; after sneezing, coughing, eating, drinking, or smoking; after handling raw meat, poultry, seafood, dirty dishes, trash, or money; before putting on gloves; and after switching tasks (especially raw to ready-to-eat). Procedure: wet hands with warm running water (100F+), apply liquid soap, lather for at least 20 seconds covering palms, backs, between fingers, under nails, and forearms, rinse thoroughly, dry with a single-use paper towel, and use that towel to turn off the faucet.`,
    `اغسل يديك قبل بدء العمل؛ وبعد استخدام دورة المياه؛ وبعد لمس الشعر أو الوجه أو الجسم؛ وبعد العطس أو السعال أو الأكل أو الشرب أو التدخين؛ وبعد التعامل مع اللحوم النيئة أو الدواجن أو المأكولات البحرية أو الأطباق المتسخة أو القمامة أو النقود؛ وقبل ارتداء القفازات؛ وبعد تغيير المهام (خاصة من النيء إلى الجاهز للأكل). الطريقة: بلّل يديك بماء جارٍ دافئ (100 °ف فأكثر)، وضع صابونًا سائلًا، وافرك لمدة 20 ثانية على الأقل الكفين وظهر اليدين وبين الأصابع وتحت الأظافر والساعدين، واشطف جيدًا، وجفف بمنشفة ورقية للاستخدام مرة واحدة، واستخدمها لإغلاق الصنبور.`,
    `Lavez-vous les mains avant de commencer ; après les toilettes ; après avoir touché cheveux, visage ou corps ; après avoir éternué, toussé, mangé, bu ou fumé ; après avoir manipulé viande crue, volaille, produits de la mer, vaisselle sale, déchets ou argent ; avant de mettre des gants ; et en changeant de tâche (surtout du cru au prêt à consommer). Méthode : mouillez les mains à l'eau courante chaude (100 °F et plus), appliquez du savon liquide, frottez au moins 20 secondes paumes, dos, entre les doigts, sous les ongles et avant-bras, rincez abondamment, séchez avec un essuie-mains à usage unique et utilisez-le pour fermer le robinet.`],
  [`Personal hygiene standards followed`,
    `الالتزام بمعايير النظافة الشخصية`,
    `Règles d'hygiène personnelle respectées`],
  [`Only a plain ring is allowed - no watches, bracelets, or decorative rings. Fingernails short, clean, and unpolished, with no artificial nails. Hair restrained in a hat or hairnet; facial hair covered with a beard net if applicable. Clean uniform/apron daily, removed before using the restroom. Smoking only in designated areas with handwashing after; eating and drinking only in designated break areas.`,
    `يُسمح بخاتم بسيط فقط - لا ساعات ولا أساور ولا خواتم زينة. الأظافر قصيرة ونظيفة وبلا طلاء، ولا أظافر صناعية. الشعر مثبت بقبعة أو شبكة شعر؛ وشعر الوجه مغطى بشبكة لحية عند الحاجة. زي/مريلة نظيفة يوميًا، تُخلع قبل استخدام دورة المياه. التدخين فقط في الأماكن المخصصة مع غسل اليدين بعده؛ والأكل والشرب فقط في أماكن الاستراحة المخصصة.`,
    `Seule une alliance simple est autorisée - ni montre, ni bracelet, ni bague décorative. Ongles courts, propres, sans vernis ni faux ongles. Cheveux maintenus sous une toque ou une charlotte ; barbe couverte d'un couvre-barbe le cas échéant. Tenue/tablier propre chaque jour, retiré avant d'aller aux toilettes. Fumer uniquement dans les zones prévues, puis se laver les mains ; manger et boire uniquement dans les zones de pause.`],
  [`Illness policy followed`,
    `الالتزام بسياسة المرض`,
    `Politique maladie respectée`],
  [`Staff must report vomiting, diarrhea, jaundice, sore throat with fever, an infected wound or boil, or a diagnosis of norovirus, hepatitis A, shigella, E. coli, or salmonella, and cannot work with food while symptomatic. Staff must be symptom-free for 24-48 hours (per local health department) before returning, and a diagnosed illness may need medical clearance first.`,
    `يجب على الموظفين الإبلاغ عن القيء أو الإسهال أو اليرقان أو التهاب الحلق مع الحمى أو جرح ملتهب أو دمّل، أو تشخيص بفيروس نورو أو التهاب الكبد A أو الشيغيلا أو الإشريكية القولونية (E. coli) أو السالمونيلا، ولا يجوز لهم العمل مع الغذاء أثناء ظهور الأعراض. يجب أن يكون الموظف خاليًا من الأعراض لمدة 24-48 ساعة (حسب الجهة الصحية المحلية) قبل العودة، وقد يتطلب المرض المشخَّص تصريحًا طبيًا أولًا.`,
    `Le personnel doit signaler vomissements, diarrhée, jaunisse, mal de gorge avec fièvre, plaie infectée ou furoncle, ou un diagnostic de norovirus, hépatite A, shigella, E. coli ou salmonelle, et ne peut pas travailler au contact des aliments tant qu'il présente des symptômes. Il doit être sans symptôme depuis 24-48 heures (selon l'autorité sanitaire locale) avant de reprendre, et une maladie diagnostiquée peut nécessiter d'abord un certificat médical.`],
  [`Glove use followed correctly`,
    `استخدام القفازات بشكل صحيح`,
    `Port des gants correctement respecté`],
  [`Gloves do not replace handwashing - wash hands before putting gloves on. Change gloves when torn or contaminated, between raw and ready-to-eat foods, after touching face, hair, or non-food surfaces or money, and at least every 4 hours during continuous use. Remove gloves before leaving the food prep area, and never wash and reuse a glove.`,
    `القفازات لا تغني عن غسل اليدين - اغسل يديك قبل ارتدائها. غيّر القفازات عند تمزقها أو تلوثها، وبين الأطعمة النيئة والجاهزة للأكل، وبعد لمس الوجه أو الشعر أو الأسطح غير الغذائية أو النقود، وكل 4 ساعات على الأقل عند الاستخدام المتواصل. اخلع القفازات قبل مغادرة منطقة تحضير الطعام، ولا تغسل قفازًا وتعيد استخدامه أبدًا.`,
    `Les gants ne remplacent pas le lavage des mains - lavez-vous les mains avant de les enfiler. Changez de gants s'ils sont déchirés ou contaminés, entre aliments crus et prêts à consommer, après avoir touché visage, cheveux, surfaces non alimentaires ou argent, et au moins toutes les 4 heures en usage continu. Retirez-les avant de quitter la zone de préparation et ne lavez jamais un gant pour le réutiliser.`],

  // --- SOP 6: Greeting & Seating --------------------------------------
  [`Guest greeted within 30 seconds of entry`,
    `الترحيب بالضيف خلال 30 ثانية من دخوله`,
    `Client accueilli dans les 30 secondes suivant son arrivée`],
  [`Make eye contact and smile. Greet warmly ("Welcome to [Restaurant Name]!"). If busy, say "We'll be right with you" and acknowledge their presence.`,
    `انظر في عيني الضيف وابتسم. رحّب بحرارة («أهلًا بكم في [اسم المطعم]!»). إن كنت مشغولًا، قل «سنكون معكم حالًا» وأشعِره بأنك لاحظت وجوده.`,
    `Regardez le client dans les yeux et souriez. Accueillez-le chaleureusement (« Bienvenue chez [nom du restaurant] ! »). En cas d'affluence, dites « Nous sommes à vous tout de suite » et montrez que vous l'avez vu.`],
  [`Party assessed and reservation checked`,
    `تقييم المجموعة والتحقق من الحجز`,
    `Groupe évalué et réservation vérifiée`],
  [`Ask how many are in the party. Note any special needs (high chair or booster, wheelchair accessibility, booth vs. table preference) and check for a reservation.`,
    `اسأل عن عدد أفراد المجموعة. دوّن أي احتياجات خاصة (كرسي أطفال عالٍ أو مقعد رافع، إمكانية الوصول بالكرسي المتحرك، تفضيل الركن أو الطاولة) وتحقق من وجود حجز.`,
    `Demandez combien de personnes composent le groupe. Notez les besoins particuliers (chaise haute ou rehausseur, accès fauteuil roulant, préférence banquette ou table) et vérifiez s'il y a une réservation.`],
  [`Wait managed correctly when no tables available`,
    `إدارة الانتظار بشكل صحيح عند عدم توفر طاولات`,
    `Attente bien gérée en l'absence de table disponible`],
  [`Give an honest wait-time estimate, offer to add the guest's name to the waitlist, and explain the wait process. Suggest bar seating if available, and update the guest every 10 minutes if the wait runs over estimate.`,
    `أعطِ تقديرًا صادقًا لوقت الانتظار، واعرض إضافة اسم الضيف إلى قائمة الانتظار، واشرح آلية الانتظار. اقترح الجلوس في البار إن كان متاحًا، وأطلع الضيف على المستجدات كل 10 دقائق إن تجاوز الانتظار التقدير.`,
    `Donnez une estimation honnête du temps d'attente, proposez d'inscrire le client sur la liste d'attente et expliquez le fonctionnement. Proposez le bar si possible et tenez le client informé toutes les 10 minutes si l'attente dépasse l'estimation.`],
  [`Table selected appropriately`,
    `اختيار الطاولة المناسبة`,
    `Table choisie de façon appropriée`],
  [`Assign to the server with the lightest section when possible. Avoid seating large parties near small tables, seat families with children away from business diners, and rotate sections fairly among servers.`,
    `خصّص الطاولة للنادل صاحب القسم الأخف كلما أمكن. تجنب إجلاس المجموعات الكبيرة قرب الطاولات الصغيرة، وأجلس العائلات مع الأطفال بعيدًا عن ضيوف الأعمال، ووزّع الأقسام بالتناوب العادل بين الندلاء.`,
    `Attribuez la table au serveur dont le rang est le moins chargé si possible. Évitez de placer les grands groupes près des petites tables, installez les familles avec enfants loin des repas d'affaires et faites tourner équitablement les rangs entre serveurs.`],
  [`Guest seated properly`,
    `إجلاس الضيف بشكل صحيح`,
    `Client correctement installé`],
  [`Walk at the guest's pace, looking back to confirm they are following. Pull out chairs if appropriate, present a menu to each guest, remove extra place settings if the party is smaller than the table setup, and bring high chairs or boosters immediately.`,
    `امشِ بسرعة الضيف، والتفت للتأكد من أنه يتبعك. اسحب الكراسي إن كان ذلك مناسبًا، وقدّم قائمة لكل ضيف، وارفع أدوات المائدة الزائدة إن كانت المجموعة أصغر من تجهيز الطاولة، وأحضر كراسي الأطفال أو المقاعد الرافعة فورًا.`,
    `Marchez au rythme du client en vous retournant pour vérifier qu'il suit. Tirez les chaises si c'est approprié, remettez une carte à chaque convive, retirez les couverts en trop si le groupe est plus petit que la table, et apportez aussitôt chaises hautes ou rehausseurs.`],
  [`Server notified of new table`,
    `إبلاغ النادل بالطاولة الجديدة`,
    `Serveur prévenu de la nouvelle table`],
  [`Inform the server ("Table 12 is seated"), note any special requests or needs, and update the seating chart or system.`,
    `أبلغ النادل («تم إجلاس الطاولة 12»)، ودوّن أي طلبات أو احتياجات خاصة، وحدّث مخطط الجلوس أو النظام.`,
    `Prévenez le serveur (« La table 12 est installée »), notez les demandes ou besoins particuliers et mettez à jour le plan de salle ou le système.`],
  [`Server greeted the table within 1-2 minutes`,
    `ترحيب النادل بالطاولة خلال 1-2 دقيقة`,
    `Serveur passé à la table en 1-2 minutes`],
  [`Approach with a smile, introduce yourself by name, offer beverages, and briefly mention specials or note that you will return to discuss them.`,
    `اقترب مبتسمًا، وعرّف بنفسك باسمك، واعرض المشروبات، واذكر الأطباق الخاصة باختصار أو أخبرهم أنك ستعود للحديث عنها.`,
    `Approchez avec le sourire, présentez-vous par votre prénom, proposez des boissons et mentionnez brièvement les suggestions ou indiquez que vous reviendrez les présenter.`],

  // --- SOP 7: Order Taking & POS --------------------------------------
  [`Beverages returned within 3-5 minutes`,
    `إحضار المشروبات خلال 3-5 دقائق`,
    `Boissons servies en 3-5 minutes`],
  [`Deliver drinks from the guest's right side with your right hand, announcing each one as you place it. Ask if guests are ready to order or need more time; if they need time, let them know you will check back shortly.`,
    `قدّم المشروبات من الجهة اليمنى للضيف بيدك اليمنى، معلنًا اسم كل مشروب عند وضعه. اسأل إن كان الضيوف مستعدين للطلب أو يحتاجون وقتًا؛ إن احتاجوا وقتًا، أخبرهم أنك ستعود قريبًا.`,
    `Servez les boissons par la droite du client, de la main droite, en annonçant chacune en la posant. Demandez si les clients sont prêts à commander ou s'ils ont besoin de temps ; dans ce cas, dites-leur que vous repassez bientôt.`],
  [`Order taken correctly`,
    `أخذ الطلب بشكل صحيح`,
    `Commande correctement prise`],
  [`Stand to the side of the table, not hovering, and take orders in a logical order. Write seat numbers to ensure correct delivery later, and record each guest's starter, main course with temperature if applicable, sides, and any modifications or allergies.`,
    `قف بجانب الطاولة دون أن تحوم فوق الضيوف، وخذ الطلبات بترتيب منطقي. اكتب أرقام المقاعد لضمان التقديم الصحيح لاحقًا، وسجّل لكل ضيف المقبلات والطبق الرئيسي مع درجة الاستواء إن وُجدت، والأطباق الجانبية، وأي تعديلات أو حساسية.`,
    `Tenez-vous sur le côté de la table, sans surplomber, et prenez les commandes dans un ordre logique. Notez les numéros de place pour servir correctement ensuite, et relevez pour chaque convive l'entrée, le plat avec la cuisson le cas échéant, les accompagnements et toute modification ou allergie.`],
  [`Key clarifying questions asked`,
    `طرح الأسئلة التوضيحية الأساسية`,
    `Questions de précision essentielles posées`],
  [`Ask how items should be cooked, which side dishes are wanted, soup or salad if included, dressing choice for salads, and whether there is anything else needed.`,
    `اسأل عن درجة طهي الأصناف، والأطباق الجانبية المطلوبة، والشوربة أو السلطة إن كانت ضمن الوجبة، ونوع الصلصة للسلطات، وإن كان هناك أي شيء آخر مطلوب.`,
    `Demandez la cuisson souhaitée, les accompagnements, soupe ou salade si incluse, l'assaisonnement des salades et s'il faut autre chose.`],
  [`Allergy alert handled correctly`,
    `التعامل مع تنبيه الحساسية بشكل صحيح`,
    `Alerte allergie correctement gérée`],
  [`If a guest mentions an allergy, take it very seriously: write "ALLERGY" in large letters on the ticket, notify the kitchen manager immediately, verify ingredients do not contain the allergen, tell the guest if an item cannot be made safely, ensure a dedicated prep area and utensils are used, and communicate to everyone involved in the order.`,
    `إذا ذكر الضيف حساسية، فتعامل معها بجدية تامة: اكتب «حساسية» بخط كبير على التذكرة، وأبلغ مدير المطبخ فورًا، وتحقق أن المكونات لا تحتوي على مسبب الحساسية، وأخبر الضيف إن تعذّر تحضير صنف بأمان، وتأكد من استخدام منطقة تحضير وأدوات مخصصة، وأبلغ كل من له علاقة بالطلب.`,
    `Si un client mentionne une allergie, prenez-la très au sérieux : écrivez « ALLERGIE » en gros sur le bon, prévenez immédiatement le chef de cuisine, vérifiez que les ingrédients ne contiennent pas l'allergène, dites au client si un plat ne peut pas être préparé sans risque, veillez à utiliser une zone et des ustensiles dédiés, et informez toutes les personnes impliquées dans la commande.`],
  [`Upselling done appropriately`,
    `البيع الإضافي بأسلوب مناسب`,
    `Vente additionnelle faite de façon appropriée`],
  [`Suggest appetizers if none were ordered, recommend premium sides or add-ons, and mention desserts and specialty drinks - genuinely, not pushily.`,
    `اقترح المقبلات إن لم تُطلب، وأوصِ بالأطباق الجانبية المميزة أو الإضافات، واذكر الحلويات والمشروبات الخاصة - بصدق ودون إلحاح.`,
    `Proposez des entrées si aucune n'a été commandée, recommandez des accompagnements ou suppléments premium, et mentionnez desserts et boissons spéciales - sincèrement, sans insister.`],
  [`Order repeated back for accuracy`,
    `إعادة الطلب للتأكد من دقته`,
    `Commande répétée pour vérification`],
  [`Briefly repeat each person's order, confirm any modifications, and ask if everything was captured correctly.`,
    `أعد باختصار طلب كل شخص، وأكّد أي تعديلات، واسأل إن كان كل شيء قد سُجّل بشكل صحيح.`,
    `Répétez brièvement la commande de chacun, confirmez les modifications et demandez si tout est correct.`],
  [`Order entered into POS immediately and correctly`,
    `إدخال الطلب في نقطة البيع فورًا وبشكل صحيح`,
    `Commande saisie en caisse immédiatement et correctement`],
  [`Enter all items accurately using modifier buttons for temperature, sides/options, substitutions, and special instructions, with allergies highlighted prominently. Assign items to the correct seat numbers, fire courses appropriately (appetizers first, mains delayed or fired via the course function), print the kitchen ticket, and verify it printed correctly before leaving the POS.`,
    `أدخل جميع الأصناف بدقة مستخدمًا أزرار التعديل لدرجة الاستواء والأطباق الجانبية/الخيارات والاستبدالات والتعليمات الخاصة، مع إبراز الحساسية بوضوح. اربط الأصناف بأرقام المقاعد الصحيحة، وأرسل الأطباق بالترتيب المناسب (المقبلات أولًا، والأطباق الرئيسية مؤجلة أو تُرسل عبر وظيفة ترتيب الأطباق)، واطبع تذكرة المطبخ وتأكد من طباعتها بشكل صحيح قبل مغادرة نقطة البيع.`,
    `Saisissez tous les articles avec précision à l'aide des modificateurs (cuisson, accompagnements/options, substitutions, instructions particulières), allergies bien mises en évidence. Affectez les articles aux bons numéros de place, envoyez les plats au bon moment (entrées d'abord, plats différés ou envoyés via la fonction « suite »), imprimez le bon cuisine et vérifiez qu'il est bien sorti avant de quitter la caisse.`],

  // --- SOP 8: Food Running & Service ----------------------------------
  [`Food quality checked before leaving the kitchen`,
    `فحص جودة الطعام قبل مغادرته المطبخ`,
    `Qualité des plats vérifiée avant la sortie de cuisine`],
  [`Respond promptly when the kitchen calls an order up. Check the ticket against the plates, and inspect presentation: proper portions, correct garnishes, clean plate rims, and correct temperature (hot food hot, cold food cold). If there is an issue, address it with the kitchen before taking the food to the table.`,
    `استجب فورًا عندما ينادي المطبخ على طلب جاهز. طابق التذكرة مع الأطباق، وافحص التقديم: الحصص الصحيحة، والزينة الصحيحة، ونظافة حواف الأطباق، والحرارة الصحيحة (الساخن ساخن والبارد بارد). إن وُجدت مشكلة، عالجها مع المطبخ قبل أخذ الطعام إلى الطاولة.`,
    `Réagissez rapidement à l'appel de la cuisine. Comparez le bon aux assiettes et vérifiez la présentation : portions correctes, bonnes garnitures, bords propres et bonne température (chaud bien chaud, froid bien froid). En cas de problème, réglez-le avec la cuisine avant d'apporter le plat.`],
  [`Service tray loaded safely`,
    `تحميل صينية الخدمة بأمان`,
    `Plateau de service chargé en sécurité`],
  [`Place heavier items in the center and balance the tray's weight evenly. Keep hot and cold items separate, confirm stability before lifting, and use a tray stand near the table.`,
    `ضع الأصناف الأثقل في المنتصف ووزّع الوزن بالتساوي على الصينية. افصل الساخن عن البارد، وتأكد من الثبات قبل الرفع، واستخدم حامل الصينية قرب الطاولة.`,
    `Placez les éléments les plus lourds au centre et répartissez le poids uniformément. Séparez le chaud du froid, vérifiez la stabilité avant de soulever et utilisez un porte-plateau près de la table.`],
  [`Table approached correctly`,
    `الاقتراب من الطاولة بشكل صحيح`,
    `Approche de la table correcte`],
  [`Approach from the guest's right side and set the tray on a stand if used.`,
    `اقترب من الجهة اليمنى للضيف وضع الصينية على الحامل إن استُخدم.`,
    `Approchez par la droite du client et posez le plateau sur un porte-plateau le cas échéant.`],
  [`Food delivered accurately and properly`,
    `تقديم الطعام بدقة وبشكل صحيح`,
    `Plats servis avec exactitude et dans les règles`],
  [`Announce each dish as you place it, using seat numbers from the order to confirm accuracy. Serve from the guest's right with your right hand, never reaching across guests, and place the main protein at the 6 o'clock position. If unsure who ordered what, ask politely.`,
    `أعلن اسم كل طبق عند وضعه، مستعينًا بأرقام المقاعد في الطلب للتأكد من الدقة. قدّم من الجهة اليمنى للضيف بيدك اليمنى، دون أن تمد يدك فوق الضيوف، وضع البروتين الرئيسي عند موضع الساعة 6. إن لم تكن متأكدًا من صاحب الطلب، اسأل بلطف.`,
    `Annoncez chaque plat en le posant, en vous aidant des numéros de place pour ne pas vous tromper. Servez par la droite du client, de la main droite, sans jamais passer le bras devant un convive, et placez la protéine principale à 6 heures. En cas de doute sur qui a commandé quoi, demandez poliment.`],
  [`Final delivery check completed`,
    `إتمام الفحص النهائي بعد التقديم`,
    `Vérification finale du service effectuée`],
  [`Ask if there is anything else needed right now, verify condiments are on the table, refill water glasses, and wish the guests a good meal.`,
    `اسأل إن كان هناك أي شيء آخر مطلوب الآن، وتأكد من وجود التوابل على الطاولة، وأعد ملء أكواب الماء، وتمنَّ للضيوف وجبة شهية.`,
    `Demandez s'il faut autre chose dans l'immédiat, vérifiez que les condiments sont sur la table, remplissez les verres d'eau et souhaitez un bon appétit.`],
  [`Two-minute check-back performed`,
    `إجراء المتابعة بعد دقيقتين`,
    `Passage de contrôle à deux minutes effectué`],
  [`Return to the table after guests have had a couple of bites (roughly 2 minutes) and ask how everything is tasting. Address any issues immediately - refire for wrong temperature, reprioritize for an incorrect order, or remove and offer a replacement for a quality issue - and refill beverages as needed.`,
    `عُد إلى الطاولة بعد أن يتناول الضيوف بضع لقيمات (نحو دقيقتين) واسأل عن رأيهم في الطعام. عالج أي مشكلة فورًا - أعد الطهي إن كانت درجة الاستواء خاطئة، أو قدّم أولوية للطلب الخاطئ، أو ارفع الطبق واعرض بديلًا لمشكلة في الجودة - وأعد تعبئة المشروبات حسب الحاجة.`,
    `Revenez à la table après les premières bouchées (environ 2 minutes) et demandez si tout est bon. Réglez tout problème immédiatement - relancez en cas de mauvaise cuisson, faites passer en priorité une commande erronée, ou retirez et proposez un remplacement en cas de problème de qualité - et resservez les boissons si besoin.`],

  // --- SOP 9: Complaint Handling --------------------------------------
  [`Complaint listened to actively`,
    `الاستماع للشكوى بإنصات`,
    `Réclamation écoutée activement`],
  [`Let the guest fully explain without interrupting, make eye contact and nod to show you are listening, do not get defensive or make excuses, and take the complaint seriously no matter how minor it seems.`,
    `دع الضيف يشرح كاملًا دون مقاطعة، وانظر في عينيه وأومئ لتُظهر أنك تستمع، ولا تتخذ موقفًا دفاعيًا أو تختلق الأعذار، وتعامل مع الشكوى بجدية مهما بدت بسيطة.`,
    `Laissez le client s'exprimer entièrement sans l'interrompre, regardez-le et hochez la tête pour montrer votre écoute, ne vous justifiez pas et ne cherchez pas d'excuses, et prenez la réclamation au sérieux, aussi mineure soit-elle.`],
  [`Empathy and apology given`,
    `إظهار التعاطف وتقديم الاعتذار`,
    `Empathie exprimée et excuses présentées`],
  [`Acknowledge the guest's frustration and apologize - even if it was not your fault, you represent the restaurant.`,
    `اعترف بانزعاج الضيف واعتذر - حتى لو لم يكن الخطأ خطأك، فأنت تمثل المطعم.`,
    `Reconnaissez la frustration du client et excusez-vous - même si ce n'est pas votre faute, vous représentez le restaurant.`],
  [`Clarifying questions asked`,
    `طرح الأسئلة التوضيحية`,
    `Questions de précision posées`],
  [`Make sure you fully understand the issue and ask what would make it right for the guest.`,
    `تأكد من فهمك الكامل للمشكلة واسأل الضيف عمّا يرضيه لحلها.`,
    `Assurez-vous de bien comprendre le problème et demandez au client ce qui arrangerait la situation.`],
  [`Immediate action taken to resolve the issue`,
    `اتخاذ إجراء فوري لحل المشكلة`,
    `Action immédiate pour résoudre le problème`],
  [`For food issues: replace a wrong order at no charge as priority, recook undercooked or overcooked items immediately, reheat or remake cold food, or remove a quality issue from the bill and offer an alternative. For service issues: expedite remaining items (possibly comping an appetizer or dessert) for slow service, or apologize and correct a server error immediately.`,
    `لمشكلات الطعام: استبدل الطلب الخاطئ مجانًا وبأولوية، وأعد طهي الأصناف غير المستوية أو المفرطة في الطهي فورًا، وأعد تسخين الطعام البارد أو تحضيره من جديد، أو احذف الصنف ذا المشكلة من الفاتورة واعرض بديلًا. لمشكلات الخدمة: عجّل بباقي الأصناف (وربما قدّم مقبلات أو حلوى مجانًا) عند بطء الخدمة، أو اعتذر وصحّح خطأ النادل فورًا.`,
    `Problème de plat : remplacez en priorité et gratuitement une commande erronée, recuisez immédiatement un plat pas assez ou trop cuit, réchauffez ou refaites un plat froid, ou retirez de l'addition un plat défectueux et proposez une alternative. Problème de service : accélérez la suite (en offrant éventuellement une entrée ou un dessert) en cas de lenteur, ou excusez-vous et corrigez immédiatement l'erreur du serveur.`],
  [`Manager involved when required`,
    `إشراك المدير عند الحاجة`,
    `Manager impliqué si nécessaire`],
  [`Involve a manager for serious complaints (food safety, illness, or injury), when the guest remains unsatisfied after your attempts to resolve it, when a guest asks to speak with a manager, for requests of significant comps or refunds, or for complaints about other staff.`,
    `أشرك المدير في الشكاوى الجدية (سلامة الغذاء، أو المرض، أو الإصابة)، وعندما يبقى الضيف غير راضٍ بعد محاولاتك، وعندما يطلب الضيف التحدث مع المدير، وفي طلبات الخصومات أو المبالغ المستردة الكبيرة، وفي الشكاوى المتعلقة بموظفين آخرين.`,
    `Faites intervenir un manager pour les réclamations graves (sécurité alimentaire, malaise ou blessure), quand le client reste insatisfait malgré vos efforts, quand il demande à parler à un manager, pour toute demande de geste commercial ou remboursement important, ou pour une plainte visant un autre membre de l'équipe.`],
  [`Follow-up completed`,
    `إتمام المتابعة`,
    `Suivi effectué`],
  [`Check back after the issue is resolved, provide extra attention for the rest of the meal, and thank the guest for the feedback.`,
    `عُد للاطمئنان بعد حل المشكلة، وقدّم اهتمامًا إضافيًا لبقية الوجبة، واشكر الضيف على ملاحظته.`,
    `Revenez vers le client une fois le problème réglé, soyez particulièrement attentif pour le reste du repas et remerciez-le pour son retour.`],
  [`Significant complaint documented`,
    `توثيق الشكوى المهمة`,
    `Réclamation importante consignée`],
  [`Log the date, time, nature of the complaint, and resolution in the daily log so the manager can review for patterns or training needs.`,
    `سجّل التاريخ والوقت وطبيعة الشكوى وطريقة حلها في السجل اليومي ليراجعها المدير بحثًا عن أنماط أو احتياجات تدريبية.`,
    `Notez la date, l'heure, la nature de la réclamation et sa résolution dans le registre quotidien pour que le manager repère les tendances ou besoins de formation.`],
  [`Compensation guidelines followed`,
    `الالتزام بإرشادات التعويض`,
    `Règles de dédommagement respectées`],
  [`Minor issue (cold food, slow drink refill): free dessert or appetizer. Moderate issue (wrong order, long wait): comp the item that had the issue. Major issue (multiple problems, food safety): comp the entire meal or a significant discount. Always get manager approval for comps over $20.`,
    `مشكلة بسيطة (طعام بارد، بطء إعادة تعبئة المشروب): حلوى أو مقبلات مجانية. مشكلة متوسطة (طلب خاطئ، انتظار طويل): الصنف المتأثر مجانًا. مشكلة كبيرة (مشكلات متعددة، سلامة الغذاء): الوجبة كاملة مجانًا أو خصم كبير. احصل دائمًا على موافقة المدير للتعويضات التي تتجاوز 20$.`,
    `Problème mineur (plat froid, boisson resservie lentement) : dessert ou entrée offert. Problème modéré (erreur de commande, longue attente) : offrir le plat concerné. Problème majeur (plusieurs problèmes, sécurité alimentaire) : offrir tout le repas ou une remise importante. Toujours obtenir l'accord du manager pour tout geste de plus de 20 $.`],

  // --- SOP 10: Cash Handling ------------------------------------------
  [`Starting cash drawer counted and verified`,
    `عدّ درج النقدية الافتتاحي والتحقق منه`,
    `Fond de caisse de départ compté et vérifié`],
  [`Count the starting bank in front of a manager (standard bank guidance: $100-$200 in small bills with a limited number of $20s and no $50s or $100s, plus a full set of coins - adjust per restaurant). Both you and the manager sign the starting count form, keep a copy, and return the bank to your assigned till.`,
    `عدّ العهدة الافتتاحية أمام المدير (الإرشاد المعتاد: 100-200$ بفئات صغيرة مع عدد محدود من فئة 20$ ودون فئتي 50$ و100$، مع مجموعة كاملة من العملات المعدنية - تُعدَّل حسب المطعم). يوقّع كل منك ومن المدير على نموذج العد الافتتاحي، واحتفظ بنسخة، وأعد العهدة إلى الصندوق المخصص لك.`,
    `Comptez le fond de caisse devant un manager (repère habituel : 100-200 $ en petites coupures avec peu de billets de 20 $ et aucun de 50 $ ou 100 $, plus un jeu complet de pièces - à adapter au restaurant). Vous et le manager signez la fiche de comptage, gardez-en une copie et remettez le fond dans votre caisse attitrée.`],
  [`Cash payments processed correctly`,
    `معالجة المدفوعات النقدية بشكل صحيح`,
    `Paiements en espèces correctement traités`],
  [`Enter the amount due in the POS first and announce it to the guest. Accept payment and announce the amount received ("Out of $60"). Let the POS calculate change due, then count the change back to the guest starting from the bill amount and counting up to what they gave you - hand it directly to the guest rather than counting it into your own hand first.`,
    `أدخل المبلغ المستحق في نقطة البيع أولًا وأعلنه للضيف. استلم المبلغ وأعلن المبلغ المستلم («من 60$»). دع نقطة البيع تحسب الباقي، ثم عدّ الباقي للضيف بدءًا من مبلغ الفاتورة صعودًا حتى المبلغ الذي أعطاك إياه - وسلّمه مباشرة للضيف بدلًا من عدّه في يدك أولًا.`,
    `Saisissez d'abord le montant dû en caisse et annoncez-le au client. Encaissez et annoncez le montant reçu (« Sur 60 $ »). Laissez la caisse calculer la monnaie, puis rendez-la en comptant à partir du montant de l'addition jusqu'à la somme donnée - remettez-la directement au client plutôt que de la compter d'abord dans votre main.`],
  [`Credit card payments processed correctly`,
    `معالجة مدفوعات البطاقات الائتمانية بشكل صحيح`,
    `Paiements par carte correctement traités`],
  [`Take the card, swipe/insert/tap as appropriate, and if declined discreetly ask for an alternative payment. Print both merchant and customer receipts, present them for signature or approval, verify the signature matches the card if signed, and return the card and customer copy immediately - never walk away with a guest's card. Keep the merchant copy for end-of-day reconciliation.`,
    `خذ البطاقة، ومرّرها أو أدخلها أو المسها بالجهاز حسب الحالة، وإن رُفضت فاطلب بلباقة وسيلة دفع أخرى. اطبع إيصالي التاجر والعميل، وقدّمهما للتوقيع أو الموافقة، وتحقق أن التوقيع يطابق البطاقة إن وُقّع، وأعد البطاقة ونسخة العميل فورًا - لا تبتعد أبدًا ببطاقة الضيف. احتفظ بنسخة التاجر لمطابقة نهاية اليوم.`,
    `Prenez la carte, glissez/insérez/approchez-la selon le cas et, en cas de refus, demandez discrètement un autre moyen de paiement. Imprimez les tickets commerçant et client, présentez-les pour signature ou validation, vérifiez que la signature correspond à la carte le cas échéant, et rendez immédiatement la carte et le ticket client - ne vous éloignez jamais avec la carte d'un client. Gardez le ticket commerçant pour le rapprochement de fin de journée.`],
  [`Large bills checked for authenticity`,
    `التحقق من أصالة الأوراق النقدية الكبيرة`,
    `Authenticité des grosses coupures vérifiée`],
  [`Check $50 and $100 bills by holding to light and checking the watermark and security thread, or with a counterfeit detection pen if provided. If a bill looks suspicious, politely ask for an alternative payment and notify the manager. If the till does not have enough change, get change from the manager or safe before completing the transaction.`,
    `افحص أوراق 50$ و100$ برفعها أمام الضوء والتحقق من العلامة المائية والشريط الأمني، أو بقلم كشف التزوير إن توفر. إن بدت الورقة مشبوهة، اطلب بلطف وسيلة دفع أخرى وأبلغ المدير. إن لم يكن في الصندوق فكة كافية، احصل عليها من المدير أو الخزنة قبل إتمام المعاملة.`,
    `Vérifiez les billets de 50 $ et 100 $ à la lumière (filigrane et fil de sécurité) ou avec un stylo détecteur si disponible. Si un billet paraît suspect, demandez poliment un autre moyen de paiement et prévenez le manager. Si la caisse n'a pas assez de monnaie, obtenez-en auprès du manager ou du coffre avant de finaliser la transaction.`],
  [`Till drop completed and documented`,
    `إتمام سحب النقدية من الصندوق وتوثيقه`,
    `Prélèvement de caisse effectué et documenté`],
  [`When cash in the drawer exceeds $200-300, remove the excess (keeping enough for making change), count what is being dropped, and fill out a till drop envelope with your name, till number, date, time, and amount. Seal it, drop it in the safe immediately, and keep a copy of the drop slip.`,
    `عندما تتجاوز النقدية في الدرج 200-300$، اسحب الزيادة (مع إبقاء ما يكفي للفكة)، وعدّ المبلغ المسحوب، واملأ ظرف السحب باسمك ورقم الصندوق والتاريخ والوقت والمبلغ. أغلقه وضعه في الخزنة فورًا، واحتفظ بنسخة من إيصال السحب.`,
    `Quand le tiroir dépasse 200-300 $, retirez l'excédent (en gardant de quoi rendre la monnaie), comptez le montant prélevé et remplissez une enveloppe de prélèvement avec votre nom, le numéro de caisse, la date, l'heure et le montant. Scellez-la, déposez-la immédiatement au coffre et gardez une copie du bordereau.`],
  [`Cash drawer closed and reconciled`,
    `إغلاق درج النقدية ومطابقته`,
    `Tiroir-caisse clôturé et rapproché`],
  [`Run the end-of-shift report from the POS and count all cash in the drawer by denomination, writing subtotals on the count sheet. Compare the total to the POS report (starting bank plus cash sales minus till drops) - a small variance of $1-2 is acceptable, but a large variance must be recounted and investigated. Sign the count sheet, have the manager verify and sign it, note any overage or shortage, remove the starting bank for the next shift, and prepare the remaining cash for deposit.`,
    `استخرج تقرير نهاية الوردية من نقطة البيع وعدّ كل النقدية في الدرج حسب الفئات، مدونًا المجاميع الفرعية في ورقة العد. قارن الإجمالي بتقرير نقطة البيع (العهدة الافتتاحية + المبيعات النقدية - المسحوبات) - فرق بسيط بين 1-2$ مقبول، أما الفرق الكبير فيجب إعادة عدّه والتحقيق فيه. وقّع ورقة العد، ودع المدير يتحقق منها ويوقّعها، ودوّن أي زيادة أو عجز، واسحب العهدة الافتتاحية للوردية التالية، وجهّز النقدية المتبقية للإيداع.`,
    `Éditez le rapport de fin de service en caisse et comptez tout l'argent du tiroir par coupure, en notant les sous-totaux sur la feuille de comptage. Comparez le total au rapport de caisse (fond de départ + ventes en espèces - prélèvements) - un petit écart de 1-2 $ est acceptable, mais un écart important doit être recompté et analysé. Signez la feuille, faites-la vérifier et signer par le manager, notez tout excédent ou manque, retirez le fond de caisse pour le service suivant et préparez le reste pour le dépôt.`],
  [`Cash handling security rules followed`,
    `الالتزام بقواعد أمان التعامل النقدي`,
    `Règles de sécurité des espèces respectées`],
  [`Never leave the cash drawer open and unattended, and close it between transactions. Do not share your POS login or password. Report discrepancies immediately rather than waiting, and never loan money to coworkers from the till. A pattern of shortages may result in termination.`,
    `لا تترك درج النقدية مفتوحًا دون مراقبة أبدًا، وأغلقه بين المعاملات. لا تشارك بيانات دخولك أو كلمة مرورك لنقطة البيع. أبلغ عن الفروقات فورًا دون تأخير، ولا تُقرض زملاءك من الصندوق أبدًا. تكرار العجز قد يؤدي إلى إنهاء الخدمة.`,
    `Ne laissez jamais le tiroir-caisse ouvert sans surveillance et fermez-le entre deux transactions. Ne partagez pas votre identifiant ni votre mot de passe de caisse. Signalez immédiatement tout écart et ne prêtez jamais d'argent de la caisse à un collègue. Des manques répétés peuvent entraîner un licenciement.`],

  // --- SOP 11: Health Inspection Readiness ----------------------------
  [`All refrigerator/freezer temps recorded and within range`, `تسجيل جميع درجات حرارة الثلاجات/الفريزرات وهي ضمن النطاق`, `Toutes les températures des réfrigérateurs/congélateurs relevées et conformes`],
  [`Food cooking temps documented`, `توثيق درجات حرارة طهي الطعام`, `Températures de cuisson documentées`],
  [`Hot/cold holding temps checked every 2 hours`, `فحص درجات حرارة الحفظ الساخن/البارد كل ساعتين`, `Températures de maintien chaud/froid contrôlées toutes les 2 heures`],
  [`Temperature logs complete and up-to-date`, `سجلات الحرارة مكتملة ومحدّثة`, `Relevés de température complets et à jour`],
  [`All food covered and properly stored`, `كل الطعام مغطى ومخزن بشكل صحيح`, `Tous les aliments couverts et correctement stockés`],
  [`Raw meats on bottom shelves, away from ready-to-eat`, `اللحوم النيئة على الأرفف السفلية، بعيدًا عن الجاهز للأكل`, `Viandes crues en bas, loin des produits prêts à consommer`],
  [`All items labeled and dated`, `جميع الأصناف عليها ملصق وتاريخ`, `Tous les produits étiquetés et datés`],
  [`Food stored 6 inches off floor`, `تخزين الطعام على ارتفاع 6 بوصات عن الأرض`, `Aliments stockés à 6 pouces du sol`],
  [`FIFO rotation being followed`, `تطبيق تدوير الوارد أولًا صادر أولًا`, `Rotation PEPS appliquée`],
  [`No expired food in storage`, `لا طعام منتهي الصلاحية في المخزن`, `Aucun aliment périmé en stock`],
  [`All staff in clean uniforms`, `جميع الموظفين بزي نظيف`, `Toute l'équipe en tenue propre`],
  [`Hair properly restrained`, `الشعر مثبت بشكل صحيح`, `Cheveux correctement attachés et couverts`],
  [`No jewelry except plain wedding band`, `لا مجوهرات باستثناء خاتم زواج بسيط`, `Aucun bijou sauf une alliance simple`],
  [`Nails short and clean`, `الأظافر قصيرة ونظيفة`, `Ongles courts et propres`],
  [`Gloves being changed appropriately`, `تغيير القفازات بالشكل المناسب`, `Gants changés comme il se doit`],
  [`Handwashing being done properly and frequently`, `غسل اليدين يتم بشكل صحيح ومتكرر`, `Lavage des mains correct et fréquent`],
  [`All work surfaces clean and sanitized`, `جميع أسطح العمل نظيفة ومعقمة`, `Tous les plans de travail propres et désinfectés`],
  [`Sanitizer buckets at proper concentration (test with strips)`, `دلاء المطهر بالتركيز الصحيح (اختبرها بالشرائط)`, `Seaux de désinfectant à la bonne concentration (tester avec les bandelettes)`],
  [`No dirty dishes accumulating`, `لا تراكم للأطباق المتسخة`, `Pas d'accumulation de vaisselle sale`],
  [`Dishwasher reaching proper temperature`, `غسالة الأطباق تصل إلى الحرارة الصحيحة`, `Lave-vaisselle à la bonne température`],
  [`Floors clean, no spills`, `الأرضيات نظيفة وبلا انسكابات`, `Sols propres, sans liquide renversé`],
  [`Drains clear, no standing water`, `المصارف سالكة، ولا مياه راكدة`, `Siphons dégagés, pas d'eau stagnante`],
  [`All equipment in good repair`, `جميع المعدات في حالة جيدة`, `Tous les équipements en bon état`],
  [`No duct tape or temporary fixes visible`, `لا شريط لاصق أو إصلاحات مؤقتة ظاهرة`, `Aucun ruban adhésif ni réparation provisoire visible`],
  [`Gaskets on coolers/freezers intact`, `جوانات الثلاجات/الفريزرات سليمة`, `Joints des réfrigérateurs/congélateurs intacts`],
  [`Can openers clean (not rusty)`, `فتاحات العلب نظيفة (غير صدئة)`, `Ouvre-boîtes propres (non rouillés)`],
  [`Cutting boards in good condition (not scored/stained)`, `ألواح التقطيع بحالة جيدة (غير مخدوشة/ملطخة)`, `Planches à découper en bon état (ni entaillées ni tachées)`],
  [`No evidence of pests (droppings, damage)`, `لا دليل على وجود آفات (فضلات، أضرار)`, `Aucune trace de nuisibles (déjections, dégâts)`],
  [`Trash cans covered with lids`, `صناديق القمامة مغطاة بأغطيتها`, `Poubelles fermées par un couvercle`],
  [`Back door kept closed when not in use`, `الباب الخلفي مغلق عند عدم الاستخدام`, `Porte arrière fermée hors utilisation`],
  [`No holes in walls or ceilings`, `لا ثقوب في الجدران أو الأسقف`, `Aucun trou dans les murs ou plafonds`],
  [`Proper lighting in all areas`, `إضاءة مناسبة في جميع المناطق`, `Éclairage adéquat dans toutes les zones`],
  [`Hand sinks stocked (soap, towels)`, `أحواض غسل اليدين مجهزة (صابون، مناشف)`, `Lave-mains approvisionnés (savon, essuie-mains)`],
  [`Temperature logs complete`, `سجلات الحرارة مكتملة`, `Relevés de température complets`],
  [`Cleaning checklists completed and signed`, `قوائم فحص التنظيف مكتملة وموقّعة`, `Check-lists de nettoyage remplies et signées`],
  [`Employee health policy posted`, `سياسة صحة الموظفين معلّقة`, `Politique de santé du personnel affichée`],
  [`Food handler certificates current and posted`, `شهادات متداولي الأغذية سارية ومعلّقة`, `Attestations de formation à l'hygiène à jour et affichées`],
  [`Permits current and properly displayed`, `التصاريح سارية ومعروضة بشكل صحيح`, `Autorisations à jour et correctement affichées`],
  [`Inspector greeted and identification verified`,
    `الترحيب بالمفتش والتحقق من هويته`,
    `Inspecteur accueilli et identité vérifiée`],
  [`Greet the inspector professionally ("Good morning" / "Good afternoon"), then request and verify identification.`,
    `رحّب بالمفتش باحترافية («صباح الخير» / «مساء الخير»)، ثم اطلب هويته وتحقق منها.`,
    `Accueillez l'inspecteur avec professionnalisme (« Bonjour »), puis demandez et vérifiez sa carte professionnelle.`],
  [`Manager notified immediately of inspector arrival`,
    `إبلاغ المدير فورًا بوصول المفتش`,
    `Manager prévenu immédiatement de l'arrivée de l'inspecteur`],
  [`Notify the manager right away, even if it is in the middle of a rush.`,
    `أبلغ المدير فورًا، حتى لو كان ذلك في ذروة الزحام.`,
    `Prévenez le manager tout de suite, même en plein rush.`],
  [`Inspector accompanied and assisted throughout`,
    `مرافقة المفتش ومساعدته طوال الزيارة`,
    `Inspecteur accompagné et assisté tout au long de la visite`],
  [`Offer to answer questions, accompany the inspector throughout the visit taking notes, and ask for clarification if a violation is not understood.`,
    `اعرض الإجابة عن الأسئلة، ورافق المفتش طوال الزيارة مدونًا الملاحظات، واطلب توضيحًا إن لم تفهم مخالفة ما.`,
    `Proposez de répondre aux questions, accompagnez l'inspecteur pendant toute la visite en prenant des notes et demandez des précisions si une non-conformité n'est pas claire.`],
  [`Honest, professional conduct maintained with inspector`,
    `الحفاظ على سلوك صادق ومهني مع المفتش`,
    `Attitude honnête et professionnelle avec l'inspecteur`],
  [`Answer honestly - never lie or hide issues - and do not argue or become defensive if issues are found.`,
    `أجب بصدق - لا تكذب ولا تُخفِ المشكلات أبدًا - ولا تجادل أو تتخذ موقفًا دفاعيًا إن وُجدت مشكلات.`,
    `Répondez honnêtement - ne mentez jamais et ne cachez aucun problème - et ne discutez pas ni ne vous braquez si des problèmes sont relevés.`],
  [`Inspection report reviewed, signed, and copy obtained`,
    `مراجعة تقرير التفتيش وتوقيعه والحصول على نسخة`,
    `Rapport d'inspection relu, signé et copie obtenue`],
  [`Review the report before the inspector leaves and sign it (signing does not mean you agree, only that you saw it), then request a copy.`,
    `راجع التقرير قبل مغادرة المفتش ووقّعه (التوقيع لا يعني موافقتك، بل أنك اطلعت عليه فقط)، ثم اطلب نسخة.`,
    `Relisez le rapport avant le départ de l'inspecteur et signez-le (signer ne vaut pas accord, seulement prise de connaissance), puis demandez-en une copie.`],
  [`Critical violations addressed immediately`,
    `معالجة المخالفات الحرجة فورًا`,
    `Non-conformités critiques corrigées immédiatement`],
  [`Any critical violations found during the inspection must be corrected immediately, not scheduled for later.`,
    `يجب تصحيح أي مخالفات حرجة تُكتشف أثناء التفتيش فورًا، لا جدولتها لوقت لاحق.`,
    `Toute non-conformité critique relevée lors de l'inspection doit être corrigée immédiatement, pas reportée.`],
]);
